"use client";
import { useState } from "react";
import TodoForm from "./components/TodoForm";
import TodoList from "./components/TodoList";

interface Todo {
  id: number;
  name: string;
  description: string;
  dueDate: string;
  priority: "low" | "medium" | "high";
  completed: boolean;
}

export default function Home() {
  const [todos, setTodos] = useState<Todo[]>([]);

  function addTodo(newTodo: Omit<Todo, "completed">) {
    setTodos((prev) => [...prev, { ...newTodo, completed: false }]);
  }

  function toggleComplete(id: number) {
    setTodos((prev) =>
      prev.map((todo) =>
        todo.id === id ? { ...todo, completed: !todo.completed } : todo
      )
    );
  }

  function deleteTodo(id: number) {
    setTodos((prev) => prev.filter((todo) => todo.id !== id));
  }

  return (
    <main className="flex flex-col md:flex-row gap-8 p-6">
      <div className="flex-1">
        <TodoForm onAdd={addTodo} />
      </div>
      <div className="flex-1">
        <TodoList todos={todos} onToggle={toggleComplete} onDelete={deleteTodo} />
      </div>
    </main>
  );
}